CREATE TABLE "users" (
  "id" bigint PRIMARY KEY
);

CREATE TABLE "marketplaces" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL
);

CREATE TABLE "tracked_items" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "link" text UNIQUE NOT NULL,
  "source_marketplace_id" smallint NOT NULL
);

CREATE TABLE "users_tracked_items" (
  "user_id" integer,
  "item_id" integer,
  PRIMARY KEY ("user_id", "item_id")
);

ALTER TABLE "users_tracked_items" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tracked_items" ADD FOREIGN KEY ("source_marketplace_id") REFERENCES "marketplaces" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users_tracked_items" ADD FOREIGN KEY ("item_id") REFERENCES "tracked_items" ("id") DEFERRABLE INITIALLY IMMEDIATE;
